-- per-innovation description that rag's innovations table has no columns for:
-- the library page sections, authors, licence and the photos in backend/seed_media/<id>/.
CREATE TABLE IF NOT EXISTS innovation_profiles (
    innovation_id text PRIMARY KEY REFERENCES innovations(id) ON DELETE CASCADE,
    tagline text,
    program text,
    problem text,
    target_group text,
    who_can_use text,
    effectiveness text,
    authors text[] NOT NULL DEFAULT '{}',
    -- file names inside backend/seed_media/<innovation_id>/
    photos text[] NOT NULL DEFAULT '{}',
    license_name text,
    license_url text,
    source_url text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- rows generated by media/build_app_seed.py from media/innovations.json; do not edit by hand
INSERT INTO innovation_profiles (
    innovation_id, tagline, program, problem, target_group, who_can_use, effectiveness,
    authors, photos, license_name, license_url, source_url
)
VALUES
    (
        'agencja-pracy-incydentalnej',
        'Model działania Agencji Pracy Incydentalnej pomagającej osobom znajdującym się w głębokim kryzysie powrócić na rynek pracy.',
        NULL,
        'Innowacja odpowiada na trudność w powrocie na rynek pracy osób pozostajacych w głębokim/wielowymiarowym kryzysie',
        'Osoby w kryzysie bezdomności i /lub psychicznym i/lub długotrwale bezrobotne i/lub z przeszłościa kryminalną i/lub osoby z niepełnosprawnością, który to kryzys skutkuje niemożnością podjęcia pracy wiążącej się z określonym czasem czy wymiarem',
        'Agencje pracy, podmioty, organizacje pozarządowe zajmujące się aktywizacja zawodową osób w glębokim kryzysie',
        'Opracowany model wskazuje drogę legalnego zarabiania. Udział w innowacji umożliwił grupie docelowej podjęcie pracy, niewielka część grupy testującej zdecydowała się jednak z tej możliwości skorzystać (3 osoby). Wynika to z wielu barier, z których kluczowa wydaje się ta związana z brakiem gotowości do podjęcia takiej zmiany w swoim życiu, zwłaszcza, że wiązałaby się ona z częściową lub pełną rezygnacją z pobierania świadczeń socjalnych. W związku z krótkim okresem realizacji projektu, pojawiły się trudności istotnie wpływające na osiągnięcie efektów, jak chociażby niewielkie zaangażowanie zleceniodawców. W związku ze złożonością obszaru wsparcia, wydaje się to pewnym osiągnięciem i obiecującym początkiem dla dalszych zmian.',
        ARRAY['Fundacja Pestka']::text[],
        ARRAY['photo-1.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy,agencja-pracy-incydentalnej'
    ),
    (
        'autyzm-i-ja',
        'Rekomendacje dla opiekunów, nauczycieli i terapeutów dotyczące edukacji przedszkolnej i wczesnej interwencji dzieci ze spektrum autyzmu i z innymi zaburzeniami neurorozwojowymi',
        NULL,
        'Innowacja jest odpowiedzią na trudności w nawiązywaniu kontaktów, kontynuowaniu lub podtrzymaniu interakcji z drugą osobą, brak kontaktu wzrokowego - szczególnie na wczesnym etapie rozwoju dziecka, brak możliwości rozwinięcia potencjału młodego człowieka oraz ograniczony dostęp do placówek edukacyjnych.',
        'Dzieci w wieku przedszkolnym ze spektrum autyzmu.',
        'Placówki edukacji przedszkolnej, placówki wczesnej interwencji, szkoły.',
        'Rozwiązanie rzeczywiście wspiera we wspólnym i kierunkowym myśleniu o edukacji i rozwoju danego dziecka rodziców i nauczycieli / wychowawców w przedszkolu. Narzędzie on-line daje możliwość obserwacji zachowania dziecka i dostrzegania najmniejszych sygnałów zmian, dzięki którym można przeanalizować zmiany w diecie, czy zachowaniu np. innych domowników, które wpływają za zachowanie dziecka w przedszkolu czy na odwrót.',
        ARRAY['Uniwersytet Medyczny im. K. Marcinkowskiego w Poznaniu']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,autyzm-i-ja'
    ),
    (
        'bajkala',
        'Lampka włączająca kulturowo dzieci czeczeńskie',
        NULL,
        'Innowacja odpowiada na wyzwanie skutecznej integracja migrantów czeczeńskich (w szczególności dzieci), których prawidłowe funkcjonowanie w nowym kraju utrudniają bariery kulturowe, językowe, prawne i psychologiczne.',
        'Dzieci czeczeńskie przebywające w Polsce pod opieką rodziny, z nadanym statusem pobytu pozwalającymi na samodzielne funkcjonowanie rodziny',
        'Ośrodki migracyjne, szkoły podstawowe do których uczęszczają migranci, organizacje pozarządowe wspierające aktywną integrację uchodźców.',
        'Podjęte działania wykazały skuteczność mechanizmu w uruchomieniu motywacji do słuchania polskich bajek oraz w poszerzaniu kompetencji językowych. Sama forma domku okazała się także skuteczna w budowaniu sprzyjającej rozwojowi atmosfery i poprzez pozytywne skojarzenia wspierała atmosferę bezpieczeństwa i komfortu. Jednocześnie, długofalowe efekty, aby zaistnieć, wymagałyby znacznego zwiększenia skali działania, a także poszerzenia treści dostępnych w ramach tego rozwiązania. Wydaje się jednak, na podstawie doświadczeń z grupą testującą, że innowacja ma potencjał do wspierania integracji dzieci czeczeńskich w kulturze polskiej, a także zwiększania poczucia ich komfortu w bardzo trudnej sytuacji jakiej znajdują się dzieci uchodźcze.',
        ARRAY['Maria Lorenc', 'Maciej Parol']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,bajkala'
    ),
    (
        'bawita',
        'Tablica manipulacyjno terapeutyczna dla seniorów i osób z chorobami dementywnymi',
        'Inkubator Włączenia Społecznego',
        'Innowacja odpowiada na problem rozpowszechnianiasię zespołów otępiennych u osób w podeszłym wieku i pozwala zwiększyć ograniczony wachlarz narzędzi rehabilitacyjnych dedykowanych osobom dorosłym.',
        'Dorosłe osoby cierpiące na zespół otępienny we wczesnym stadium oraz osoby rehabilitowane pamięciowo po udarach i wylewach.',
        'Placówki wsparcia dziennego seniorów, domy pomocy społecznej, miejskie dzienne domy pomocy społecznej, warsztaty terapii zajęciowej, osoby indywidualne.',
        'Test innowacji potwierdził jej skuteczność w procesie poprawy pamięci proceduralnej. Wykazał także szereg dodatkowych istotnych dla rehabilitacji osób starszych efektów – poprawa motoryki małej, rozwijanie wyobraźni, skojarzeń, poprawa fluencji i rozbudowywanie pomięci słownej, a nawet poprawa funkcjonowania społecznego i integracji.',
        ARRAY['Maria Lorenc', 'Maciej Parol']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,bawita'
    ),
    (
        'bez-presji-z-depresji',
        'Komplet materiałów psychoedukacyjnych wspierających dzieci i młodzież szkolną doświadczających kryzysów psychicznych',
        NULL,
        'Innowacja odpowiada na potrzeby dzieci i młodzieży borykających się z problemami zdrowia psychicznego, które powracają do środowiska szkolnego po dłuższej nieobecności.',
        'Dzieci i młodzież w wieku od 10 do 13 lat (od 4 do 8 klasy szkoły podstawowej), które wracają do czynnego funkcjonowania w życiu społecznym po dłuższej nieobecności spowodowanej trudnościami w sferze emocji, terapią lub leczeniem psychiatrycznym związanym z zaburzeniami nastroju, kryzysami psychicznymi, stanami lękowymi oraz rodzice, rówieśnicy oraz nauczyciele, osób zmagających się z trudnościami w powrocie do funkcjonowania w życiu społecznym i szkolnym.',
        'Placówki oświatowe, poradnie psychologiczno-pedagogiczne, ośrodki interwencji kryzysowej, szpitale psychiatryczne z oddziałami dla dzieci i młodzieży.',
        'Wyniki testu pokazały, że dzięki skorzystaniu z innowacji m.in. wzrosło samopoczucie uczniów (w obszarze funkcjonowania społecznego) oraz wzrosła samoocena nauczycieli i rodziców (w obszarze znajomości narzędzi i sposobów wspierania). Minusem rozwiązania jest fakt, że podobne materiały można znaleźć w innych źródłach, a warunkiem powodzenia projektu staje się w tej sytuacji spójne, kompleksowe działanie z wielu stron (co jest wyzwaniem) i wykorzystanie kompletu produktów.',
        ARRAY['Instytut HR Ewa Gordziej-Niewczyk']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,bez-presji-z-depresji'
    ),
    (
        'bez-stresu-do-sukcesu-terapia-neurologiczna-przyjazna-dziecku',
        'Model pracy z pacjentami z niepełnosprawnością do 3. roku życia, wykorzystujący synergię pomiędzy terapią NDT, dogoterapią i psychologią dziecięcą',
        NULL,
        'Innowacja odpowiada na brak dostępu do skutecznych terapii kompleksowych dla dzieci poniżej 3. roku życia, które - oddziałując na psychikę - umożliwią zwiększenie skuteczności leczenia właściwego.',
        'Dzieci z niepełnosprawnością i zagrożone trwałą niepełnosprawnością między 6. miesiącem a 3. rokiem życia, dzieci obarczone trudnościami rozwojowymi, które odmawiają współpracy z prowadzącym, ponieważ ćwiczenia rehabilitacyjne wykraczają poza ich możliwości koncentracji i stanowią dla nich dyskomfort.',
        'Placówki fizjoterapeutyczne, rodzice/opiekunowie, ośrodki wczesnego wspomagania rozwoju, dzienne i całodobowe oddziały rehabilitacyjne.',
        'Analizując wyniki testów można przyjąć, że współpraca dwóch terapeutów przynosi oczekiwane efekty (dziewięcioro na dziesięć dzieci/opiekunów potwierdziło ich skuteczność). Pozytywny wpływ udziału drugiej osoby w procesie terapeutycznym najbardziej zauważalny był podczas pracy manualnej z dzieckiem. Większość z dzieci nie reagowała na dotyk dzięki temu fizjoterapeuta mógł pracować znacznie dłużej i efektywniej. Terapeuta mógł także skupić się dłużej na pracy z ciałem dziecka jednocześnie nie poświęcając czasu na wyciszanie trudnych emocji zakłócających przebieg terapii.',
        ARRAY['Marta Grela']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,bez-stresu-do-sukcesu-terapia-neurologiczna-przyjazna-dziecku'
    ),
    (
        'biustspinka',
        'Urządzenie wspomagające zakładanie biustonosza dla kobiet posiadających różnego typu ograniczenia ruchowe i fizyczne',
        NULL,
        'Rozwiązanie stanowi odpowiedź na problem braku odpowiednich artykułów i urządzeń wspierających samodzielne ubieranie się kobiet z dysfunkcją ręki.',
        'Kobiety posiadające różnego rodzaju ograniczenia fizyczne i ruchowe, które utrudniają lub uniemożliwiają samodzielne założenie biustonosza (m.in. poruszające się na wózku, z niepełnosprawnością wrodzoną, z mózgowym porażeniem dziecięcym, z niepełnosprawnością nabytą w wyniku wypadku lub choroby, kobiety z dysfunkcją ramienia, kobiety po amputacji piersi, kobiety z zaburzeniami ruchu w wyniku udaru lub przebytej operacji, kobiety cierpiące na otyłość).',
        'Gabinety rehabilitacyjne, szkoły, szpitale, sklepy z bielizną, przychodnie, oddziały rehabilitacyjne.',
        'Użyteczność produktu zasadza się w jego prostocie oraz możliwości całkowitej samodzielności osoby z niepełnosprawnością. Natomiast testowanie wykazało, że mimo wszystko produkt nie jest dla wszystkich wygodny w użyciu. Użyteczność produktu zostanie niewątpliwie docenione przez sprawniejsze osoby, które czynność zapinania biustonosza wykonają jedną, sprawną ręką. Wątpliwość w obszarze użyteczności dotyczy specyficznego ruchu, który wiąże się z użyciem produktu. Taśma slap, która oplata użytkowniczkę w miejscu pod biustem, musi być dosyć mocno uderzona w celu oplecenia jej wokół ciała. Dodatkowo wymaga także precyzyjnych ruchów, w celu zapięcia biustonosza na urządzenie. To wszystko sprawia, że produkt nie będzie jednakowo użyteczny dla całej, pierwotnie zakładanej grupy docelowej.',
        ARRAY['Karpatia Sp. z o. o']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,biustspinka'
    ),
    (
        'blue-sea-eye',
        'Urządzenie nawigacyjne połączone z aplikacją, które umożliwia osobom z dysfunkcją wzroku samodzielne sterowanie jednostką pływającą',
        NULL,
        'Innowacja odpowiada na brak sprzętu umożliwiającego nawigowanie żeglarzy z dysfunkcją narządu wzroku i utrudniony dostęp osób z dysfunkcją narządu wzroku do żeglarstwa.',
        'Osoby niewidome, osoby niedowidzące.',
        'Osoby z dysfunkcją narządu wzroku, podmioty organizujące rejsy uwzględniające załogantów z z dysfunkcją narządu wzroku, kluby żeglarskie, organizacje pozarządowe wspierające osoby z dysfunkcją narządu wzroku.',
        'Rozwiązanie zostało bardzo dobrze ocenione zarówno przez realizatorów innowacji, jak i członków grupy testującej, którzy wprost twierdzili „nie czuję się już jak ‘worek ziemniaków’ który ktoś musi przesuwać na pokładzie”. Blue Sea Eye jest urządzeniem dobrze zaprojektowanym, pozwalającym niewidomym, w sprzyjających warunkach pogodowych, samodzielnie sterować jednostką pływającą. Aby przedłużyć trwałość urządzenia i poprawić jego wydajność należy jednak podjąć dalsze działania, m.in. przenieść układy zawarte w gotowych komponentach do jednego układu scalonego i opracować filtrowanie i rozdzielanie zasilania.',
        ARRAY['Fundacja Zobaczyć Morze']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
        'CC BY 4.0',
        'https://creativecommons.org/licenses/by/4.0/deed.pl',
        'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,blue-sea-eye'
    ),
    (
        'brzuszkole-brzuszek-zostaje-w-przedszkolu',
        'Kompendium wiedzy oraz narzędzia w postaci list zadaniowych, ćwiczeń, które pomagają rodzicom i ich dzieciom kształtować zdrowe nawyki żywieniowe od najmłodszych lat.',
        NULL,
        'Innowacja dotyczy takich problemów jak przeciwdziałanie problemowi otyłości nadwagi i otyłości u dzieci w wieku 4-7 lat.',
        'Dzieci w wieku 4-7 la tz nadwagą/otyłością lub ryzykiem nadwagi/otyłości',
        'Placówki medyczne, przedszkola, organizacje pozarządowe.',
        'Rozwiązanie – poprzez zwiększenie dostępności do rzetelnych materiałów – jest skuteczne w podniesieniu wiedzy u rodziców o zasadach zdrowego odżywiania dzieci w wieku przedszkolny. Ponadto jest atrakcyjnym materiałem także dla samych dzieci, co sprawia, że jest skuteczne także w wymiarze zwiększania zainteresowania tym tematem dzieci. Testy wskazały, że kluczowe znaczenie w zainicjowaniu pożadanych zmian, ale także w utrzymywaniu ich trwałości ma wsparcie pediatry w tym procesie.',
        ARRAY['Justyna Laskowska']::text[],
        ARRAY['photo-1.jpg', 'photo-2.jpg']::text[],
